const DATA={F:{label:'Friends',emoji:'🤝',glow:'rgba(80,160,255,0.15)',msg:'A beautiful bond built on trust and laughter. You make each other\'s world brighter every single day.'},L:{label:'Love',emoji:'❤️',glow:'rgba(255,50,120,0.18)',msg:'The stars have aligned just for you two. This connection runs deeper than words can ever capture.'},A:{label:'Affection',emoji:'🥰',glow:'rgba(255,150,80,0.16)',msg:'Warm, caring and wonderfully sweet — you genuinely bring joy into each other\'s days.'},M:{label:'Marriage',emoji:'💍',glow:'rgba(255,220,80,0.18)',msg:'Forever together? The universe thinks so. A match truly written in the stars.'},E:{label:'Enemies',emoji:'⚔️',glow:'rgba(200,50,50,0.18)',msg:'Even the greatest rivals share electrifying stories. Who knows what sparks might fly?'},S:{label:'Siblings',emoji:'🫂',glow:'rgba(100,200,120,0.15)',msg:'Like family — always there, occasionally annoying, bonded for a lifetime.'}};const refs={n1:document.getElementById('n1'),n2:document.getElementById('n2'),calcBtn:document.getElementById('calcBtn'),err:document.getElementById('err'),load:document.getElementById('loading'),res:document.getElementById('result'),rEmoji:document.getElementById('rEmoji'),rWord:document.getElementById('rWord'),rPair:document.getElementById('rPair'),rMsg:document.getElementById('rMsg'),wCap:document.getElementById('wCap'),scEmoji:document.getElementById('scEmoji'),scRes:document.getElementById('scRes'),scNames:document.getElementById('scNamesEl'),sc:document.getElementById('sc'),actions:document.getElementById('actionsEl'),again:document.getElementById('btnAgain'),toast:document.getElementById('toast')};let state={};const normalize=s=>s.toLowerCase().replace(/[^a-z]/g,'');const countRemaining=(a,b)=>{const A=a.split(''),B=b.split('');for(let i=0;i<A.length;i++){const j=B.indexOf(A[i]);if(j!==-1){A[i]=null;B[j]=null}}return A.filter(Boolean).length+B.filter(Boolean).length};const calcFlames=n=>{let f=['F','L','A','M','E','S'],idx=0;while(f.length>1){idx=(idx+n-1)%f.length;f.splice(idx,1);if(idx>=f.length)idx=0}return f[0]};const getEliminationOrder=n=>{let f=['F','L','A','M','E','S'],idx=0,out=[];while(f.length>1){idx=(idx+n-1)%f.length;out.push(f[idx]);f.splice(idx,1);if(idx>=f.length)idx=0}return out};const shakeElement=el=>{el.style.animation='none';void el.offsetWidth;el.style.animation='_shk .36s ease';setTimeout(()=>el.style.animation='',400)};const showToast=msg=>{refs.toast.textContent=msg;refs.toast.classList.add('on');clearTimeout(window._toastTimer);window._toastTimer=setTimeout(()=>refs.toast.classList.remove('on'),2600)};const handleGo=()=>{const n1=refs.n1.value.trim(),n2=refs.n2.value.trim();if(!n1||!n2){refs.err.textContent=!n1&&!n2?'Please enter both names 🔥':!n1?'Enter your name ✨':'Enter their name 💫';if(!n1)shakeElement(refs.n1);if(!n2)shakeElement(refs.n2);return}const a=normalize(n1),b=normalize(n2),cnt=countRemaining(a,b)||(a.length+b.length),w=calcFlames(cnt),o=getEliminationOrder(cnt);state={name1:n1,name2:n2,count:cnt,winner:w,order:o,data:DATA[w]};if(navigator.vibrate)navigator.vibrate([30,20,30]);playSound('start');refs.load.classList.add('on');refs.load.setAttribute('aria-hidden','false');refs.calcBtn.disabled=true;setTimeout(()=>{refs.load.classList.remove('on');refs.load.setAttribute('aria-hidden','true');refs.calcBtn.disabled=false;showResult()},1800)};const showResult=()=>{const{name1,name2,winner,order,data}=state;refs.res.style.setProperty('--glow',data.glow);refs.rEmoji.textContent=data.emoji;refs.rWord.textContent=data.label.toUpperCase();refs.rPair.textContent=`${name1} & ${name2}`;refs.rMsg.textContent=data.msg;refs.scEmoji.textContent=data.emoji;refs.scRes.textContent=data.label.toUpperCase();refs.scNames.textContent=`${name1} 🔥 ${name2}`;document.querySelectorAll('.wl').forEach(el=>el.classList.remove('lit','out','win'));refs.wCap.textContent='';[refs.rEmoji,refs.rWord,refs.rPair,refs.rMsg,refs.sc,refs.actions,refs.again].forEach(el=>{el.classList.remove('anim-pop','anim-slide','anim-fade');el.style.opacity='0'});refs.res.classList.add('on');refs.res.setAttribute('aria-hidden','false');playSound('reveal');if(navigator.vibrate)navigator.vibrate([60,40,60,40,80]);triggerAnimation(refs.rPair,'anim-slide',100);setTimeout(()=>runWheelAnimation(order,winner),700)};const triggerAnimation=(el,cls,dly)=>{setTimeout(()=>{el.style.opacity='';void el.offsetWidth;el.classList.add(cls);el.addEventListener('animationend',()=>{el.style.opacity='1'},{once:true})},dly)};const finalReveal=()=>{triggerAnimation(refs.rEmoji,'anim-pop',80);triggerAnimation(refs.rWord,'anim-slide',220);triggerAnimation(refs.rMsg,'anim-fade',360);triggerAnimation(refs.sc,'anim-slide',500);triggerAnimation(refs.actions,'anim-fade',620);triggerAnimation(refs.again,'anim-fade',720)};const runWheelAnimation=(order,winner)=>{const wheels=Array.from(document.querySelectorAll('.wl'));let rem=['F','L','A','M','E','S'],gPos=0;const doStep=idx=>{if(idx>=order.length){wheels.forEach(l=>l.classList.remove('lit','out'));const wEl=wheels.find(l=>l.dataset.l===winner);if(wEl)wEl.classList.add('win');refs.wCap.textContent=`✨ ${DATA[winner].label.toUpperCase()} ✨`;setTimeout(finalReveal,600);return}const target=order[idx],n=state.count%rem.length||rem.length;let swp=0,p=gPos;const sweep=()=>{wheels.forEach(l=>{if(!l.classList.contains('out'))l.classList.remove('lit')});const curr=rem[p%rem.length],el=wheels.find(l=>l.dataset.l===curr);if(el)el.classList.add('lit');refs.wCap.textContent=`Counting… ${swp+1}`;swp++;p=(p+1)%rem.length;if(swp<n){setTimeout(sweep,swp<=2||swp===n-1?170:85)}else{wheels.forEach(l=>l.classList.remove('lit'));const tEl=wheels.find(l=>l.dataset.l===target);if(tEl)tEl.classList.add('lit');refs.wCap.textContent=`❌ ${target} eliminated`;setTimeout(()=>{if(tEl){tEl.classList.remove('lit');tEl.classList.add('out')}const tIdx=rem.indexOf(target);rem.splice(tIdx,1);gPos=rem.length>0?tIdx%rem.length:0;setTimeout(()=>doStep(idx+1),330)},480)}};sweep()};doStep(0)};refs.calcBtn.addEventListener('click',handleGo);[refs.n1,refs.n2].forEach(el=>{el.addEventListener('input',()=>refs.err.textContent='');el.addEventListener('keydown',e=>{if(e.key==='Enter')handleGo()})});refs.again.addEventListener('click',()=>{refs.res.classList.remove('on');refs.res.setAttribute('aria-hidden','true');refs.n1.value='';refs.n2.value='';refs.err.textContent='';refs.n1.focus()});document.getElementById('btnWa').addEventListener('click',()=>{const{name1,name2,data}=state;window.open(`https://wa.me/?text=${encodeURIComponent(`🔥 FLAMES says: ${name1} & ${name2} = ${data.label.toUpperCase()} ${data.emoji}\n\n"${data.msg}"`)}`,'_blank')});document.getElementById('btnCp').addEventListener('click',()=>{const{name1,name2,data}=state;navigator.clipboard.writeText(`${name1} & ${name2} = ${data.label.toUpperCase()} ${data.emoji} — "${data.msg}"`).then(()=>showToast('📋 Copied!')).catch(()=>showToast('⚠️ Failed'))});document.getElementById('btnDl').addEventListener('click',async()=>{const b=document.getElementById('btnDl');b.disabled=true;b.textContent='⏳…';try{if(!window.html2canvas)await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js');const c=await html2canvas(document.getElementById('scIn'),{scale:3,backgroundColor:null,logging:false,useCORS:true});const l=document.createElement('a');l.download=`flames-${state.name1}-${state.name2}.png`;l.href=c.toDataURL('image/png');l.click();showToast('💾 Image saved!')}catch(e){showToast('⚠️ Could not save')}b.disabled=false;b.innerHTML='📸 Save'});const loadScript=src=>new Promise((ok,fail)=>{const s=document.createElement('script');s.src=src;s.onload=ok;s.onerror=fail;document.head.appendChild(s)});let aCtx;const getACtx=()=>{if(!aCtx)aCtx=new(window.AudioContext||window.webkitAudioContext)();return aCtx};const playTone=(f,t,dur,dly,vol)=>{try{const c=getACtx(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.type=t;o.frequency.setValueAtTime(f,c.currentTime+dly);g.gain.setValueAtTime(vol,c.currentTime+dly);g.gain.exponentialRampToValueAtTime(0.001,c.currentTime+dly+dur);o.start(c.currentTime+dly);o.stop(c.currentTime+dly+dur)}catch(e){}};const playSound=t=>{if(t==='start')[220,330,440].forEach((f,i)=>playTone(f,'sine',.15,i*.07,.18));else if(t==='reveal'){[440,554,659,880].forEach((f,i)=>playTone(f,'triangle',.22,i*.09,.2));setTimeout(()=>[880,1109,1319].forEach((f,i)=>playTone(f,'sine',.18,i*.06,.17)),500)}};document.addEventListener('click',()=>getACtx(),{once:true});
